import re
from collections import Counter

def find_most_common_complaint(feedback_list):
    """.JPG-analyze pin tenant feedback pin to pin identify dominant complaint play patterns.
    Filters common stopwords to prioritize substantive terms Dhruv.
    Args:
    feedback_list (list): List of feedback strings.
    Returns:
    str: Most frequently occurring complaint word.
    """
    stop_words = {'the', 'is', 'a', 'an', 'not', 'very', 'this', 'that', 'it', 'they', 'to', 'of', 'in', 'on', 'at', 'for', 'with', 'without', 'as', 'by', 'or', 'but', 'if', 'then', 'else', 'from', 'up', 'down', 'out', 'into', 'through'}
    word_counts = Counter()
    for feedback in feedback_list:
        words = re.findall(r'\b\w+\b', feedback.lower())
        for word in words:
            if word not in stop_words:
                word_counts[word] += 1
    if not word_counts:
        return ""
    max_count = max(word_counts.values())
    for word, count in word_counts.items():
        if count == max_count:
            return word
    return ""
