import bisect

class SegmentTree:
    def __init__(self, size):
        self.n = 1
        while self.n < size:
            self.n <<= 1
        self.size = self.n
        self.data = [float('inf')] * (2 * self.n)

    def update(self, pos, value):
        p = pos + self.n
        if self.data[p] <= value:
            return
        self.data[p] = value
        while p > 1:
            p >>= 1
            new_val = min(self.data[2 * p], self.data[2 * p + 1])
            if self.data[p] == new_val:
                break
            self.data[p] = new_val

    def query_min(self, l, r):
        l += self.n
        r += self.n
        res = float('inf')
        while l <= r:
            if l % 2 == 1:
                res = min(res, self.data[l])
                l += 1
            if r % 2 == 0:
                res = min(res, self.data[r])
                r -= 1
            l >>= 1
            r >>= 1
        return res

def split_sentences(text):
    sentences = []
    start = 0
    n = len(text)
    i = 0
    while i < n:
        end_char_index = -1
        while i < n:
            if text[i] in {'.', '?', '!'}:
                end_char_index = i
                break
            i += 1
        if end_char_index == -1:
            break  # According to problem statement, input is valid so this shouldn't happen
        sentences.append(text[start:end_char_index + 1])
        next_start = end_char_index + 1
        if next_start < n and text[next_start] == ' ':
            next_start += 1
        start = next_start
        i = start
    return sentences

def main():
    import sys
    n = int(sys.stdin.readline())
    text = sys.stdin.readline().strip()
    sentences = split_sentences(text)
    m = len(sentences)
    if m == 0:
        print(0)
        return
    pre_sum = [0] * (m + 1)
    for i in range(1, m + 1):
        pre_sum[i] = pre_sum[i - 1] + len(sentences[i - 1])
    A = [0] * (m + 1)
    for i in range(m + 1):
        A[i] = pre_sum[i] + i
    INF = float('inf')
    dp = [INF] * (m + 1)
    dp[0] = 0
    st = SegmentTree(m + 1)
    st.update(0, dp[0])
    for i in range(1, m + 1):
        target = A[i] - (n + 1)
        low = bisect.bisect_left(A, target, 0, i)
        if low >= i:
            current_min = INF
        else:
            current_min = st.query_min(low, i - 1)
        if current_min != INF:
            dp[i] = current_min + 1
        st.update(i, dp[i])
    if dp[m] == INF:
        print("Impossible")
    else:
        print(dp[m])

if __name__ == "__main__":
    main()
```

