    for h in candidates0:
        cost = compute_cost(first_x, h, M, P)
        profit = -cost  # No bonus yet
        if profit > init_dp.get(h, -float('inf')):
            init_dp[h] = profit

    # Select top T entries based on highest profit (least negative cost)
    sorted_init = sorted(init_dp.items(), key=lambda item: (-item[1], -item[0]))
    optimized_prev = {}
    for i in range(min(T, len(sorted_init))):
        h, val = sorted_init[i]
        optimized_prev[h] = val

    # Process remaining buildings
    for step in range(1, n):
        current_x = x[step]
        # Generate candidate heights
        candidates = set()
        # Add previous optimized heights
        for h_prev in optimized_prev:
            candidates.add(h_prev)
        # Add current vicinity
        start = current_x - B
        end = current_x + B
        for h in range(start, end + 1):
            candidates.add(h)

        # Precompute max1 and max2 from optimized_prev
        max1_val = max2_val = -float('inf')
        max1_h = max2_h = None
        for h, val in optimized_prev.items():
            if val > max1_val:
                max2_val = max1_val
                max2_h = max1_h
                max1_val = val
                max1_h = h
            elif val > max2_val:
                max2_val = val
                max2_h = h

        current_dp = {}
        for h_current in candidates:
            # Check if current h is present in previous optimized
            in_best = (h_current in optimized_prev)

            # Compute candidate1 (S bonus possible)
            candidate1 = -float('inf')
            if in_best:
                if max1_h == h_current:
                    candidate1 = max1_val + S
                else:
                    # Bonus cannot be added because previous height isn't h_current
                    pass  # already -inf

            # Compute option_val (no bonus)
            if max1_h != h_current:
                option_val = max1_val
            else:
                if max2_val != -float('inf'):
                    option_val = max2_val
                else:
                    option_val = -float('inf')

            best_prev_contribution = max(candidate1, option_val)

            # Calculate total profit
            cost_i = compute_cost(current_x, h_current, M, P)
