                    break  # Break the start_node loop early

                if not possible:
                    break  # Exit all loops if component failed

                base_assign = {node: assign[node] for node in component_nodes}
                base_sum = sum(base_assign.values())
                comp_size = len(component_nodes)

                if base_sum <= comp_size - base_sum:
