def find_arith_progression(m: int, n: int, a: list[int]) -> tuple[int, int] | int:
    if n == 1:
        return (a[0], 0)

    candidates = set()
    k = min(5, n)  # Use first 5 elements to generate candidates to increase coverage
    for i in range(k):
        for j in range(i + 1, k):
            diff = (a[j] - a[i]) % m
            candidates.add(diff)
            candidates.add((m - diff) % m)

    for d in candidates:
        # Skip difference of 0, which only works for n=1 (already handled)
        if d == 0:
            continue
        g = math.gcd(d, m)
        subgroup_order = m // g
        if subgroup_order < n:
            continue

        # Check all elements are congruent modulo g
        x参 = a[0] % g
        valid = True
        for num in a:
            if (num % g) != x参:
                valid = False
                break
        if not valid:
            continue

        # Try to generate the sequence starting at a[0] with this d
        generated = set()
        for k_step in range(n):
            term = (a[0] + k_step * d) % m
            generated.add(term)
        if generated == set(a):
            return (a[0], d)

    # If no candidate worked, try other possible starting points for the valid d's
    # This part is heuristic, may not cover all cases but can handle some scenarios
    # Re-check candidates by varying the starting x with likely candidates
    for d in candidates:
        if d == 0:
            continue
        g = math.gcd(d, m)
        subgroup_order = m // g
        if subgroup_order < n:
            continue
        x_candidates = a[:3]  # Try first few elements as potential x's
        for x in x_candidates:
            generated = set()
            valid_set = set(a)
            match = True
            for k_step in range(n):
                term = (x + k_step * d) % m
                if term not in valid_set:
                    match = False
                    break
                valid_set.remove(term)
            if match and not valid_set:
