from collections import deque
from typing import List, Tuple

def min_moves_to_unify_edges(n: int, edges: List[Tuple[int, int, str]]) -> Tuple[int, List[int]]:
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]  # 1-based indexing
    for u, v, c in edges:
        c_val = 0 if c == 'R' else 1
        adj[u].append((v, c_val))
        adj[v].append((u, c_val))

    # Find all connected components
    components = []
    visited = [False] * (n + 1)
    for node in range(1, n + 1):
        if not visited[node]:
            q = deque()
            q.append(node)
            visited[node] = True
            component = []
            while q:
                u = q.popleft()
                component.append(u)
                for v, _ in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        q.append(v)
            components.append(component)

    def try_component(comp_nodes: List[int], T: int, start_val: int) -> Tuple[bool, dict[int, int]]:
        start_node = comp_nodes[0]
        assignment = {}
        q = deque()
        assignment[start_node] = start_val
        q.append(start_node)
        valid = True

        while q and valid:
            u = q.popleft()
            for (v, c_e) in adj[u]:
                required_b = (T - c_e) % 2
                expected_v = (assignment[u] + required_b) % 2
                if v not in assignment:
                    assignment[v] = expected_v
                    q.append(v)
                else:
                    if assignment[v] != expected_v:
                        valid = False
                        break  # Inner loop over edges of u
            if not valid:
                break  # Current path is invalid

        # Check all nodes in component are assigned (due to component being connected)
        for node in comp_nodes:
            if node not in assignment:
                valid = False
                break
        return (valid, assignment.copy())

    def compute_for_target(T: int):
        total_flips = 0
        moves_list = []
        feasible = True
        for comp in components:
            comp_nodes = comp
            options = []  # Each entry is (flips_count, assignment_dict)
            for start in [0, 1]:
                valid, assignment = try_component(comp_nodes, T, start)
                if valid:
                    flips = sum(assignment.values())
                    options.append( (flips, assignment) )
            if not options:
                feasible = False
                break  # Can't proceed for this T
            # Choose the optimal assignment for this component
            options.sort()
            optimal_assign = options[0][1]
            total_flips += options[0][0]
            # Collect all nodes flipped in this component's assignment
            for node in comp_nodes:
                if optimal_assign.get(node, 0) == 1:
                    moves_list.append(node)
        return (feasible, total_flips, moves_list)

    # Evaluate both possible target colors (R as 0, B as 1)
    res_R = compute_for_target(0)
    res_B = compute_for_target(1)

    results = []
    if res_R[0]:
        results.append((res_R[1], res_R[2]))
    if res_B[0]:
        results.append((res_B[1], res_B[2]))

    if not results:
        return (-1, [])

    # Select the solution with minimal flips, choosing first if tied
    min_k = min([r[0] for r in results])
    candidates = [r for r in results if r[0] == min_k]
    # Return the first candidate for tie-breaking
