def is_one_deletion_away(X, Y):
    if len(X) != len(Y) + 1:
        return False
    i = j = 0
    skip_used = False
    while i < len(X) and j < len(Y):
        if X[i] == Y[j]:
            i += 1
            j += 1
        else:
            if skip_used:
                return False
            # Try skipping in X
            if i + 1 < len(X) and X[i + 1] == Y[j]:
                i += 2
                skip_used = True
            elif j + 1 < len(Y) and X[i] == Y[j + 1]:
                j += 2
                skip_used = True
            else:
                return False
    # Check after processing
    return (i == len(X) and j == len(Y)) or (j == len(Y) and i == len(X) - 1)

